A generic REST service wrapper class in C# that includes authentication token handling can be implemented using the `HttpClient` class. In the example below, I will create a simple wrapper for a REST service that helps you incorporate token handling with GET and POST requests.

```csharp
using System;
using System.Net.Http;
using System.Net.Http.Headers;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class RestServiceWrapper
{
    private readonly HttpClient _httpClient;
    private string _authToken;

    public RestServiceWrapper()
    {
        _httpClient = new HttpClient();
    }

    public void SetAuthToken(string token)
    {
        _authToken = token;
    }

    public async Task<string> GetAsync(string uri)
    {
        HttpResponseMessage response;

        if (!string.IsNullOrEmpty(_authToken))
        {
            _httpClient.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", _authToken);
        }

        response = await _httpClient.GetAsync(uri);

        if (response.IsSuccessStatusCode)
        {
            return await response.Content.ReadAsStringAsync();
        }

        throw new Exception($"Request failed with status code {response.StatusCode}");
    }

    public async Task<string> PostAsync<T>(string uri, T data)
    {
        HttpResponseMessage response;
        string jsonString = JsonConvert.SerializeObject(data);
        StringContent content = new StringContent(jsonString, Encoding.UTF8, "application/json");

        if (!string.IsNullOrEmpty(_authToken))
        {
            _httpClient.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", _authToken);
        }

        response = await _httpClient.PostAsync(uri, content);

        if (response.IsSuccessStatusCode)
        {
            return await response.Content.ReadAsStringAsync();
        }

        throw new Exception($"Request failed with status code {response.StatusCode}");
    }
}
```

